(function(){(window.upwHoverFx=window.upwHoverFx||{}).magnetic_letters={pointer:!0,reduceSkip:!0,run:function(t){if(!t.__upwML){t.__upwML=!0;var i=t.textContent;if(i){t.textContent="";for(var e=[],v=0;v<i.length;v++){var a=document.createElement("span");a.className="sc-hover-ml-char",a.textContent=i[v],t.appendChild(a),e.push(a)}var l=parseFloat(t.getAttribute("data-hover-ml-strength"))||1,c=80;t.addEventListener("pointermove",function(r){for(var n=0;n<e.length;n++){var o=e[n].getBoundingClientRect(),u=r.clientX-(o.left+o.width/2),s=r.clientY-(o.top+o.height/2),h=Math.sqrt(u*u+s*s);if(h<c){var f=(1-h/c)*l*.4;e[n].style.transform="translate("+(u*f).toFixed(1)+"px,"+(s*f).toFixed(1)+"px)"}else e[n].style.transform=""}}),t.addEventListener("pointerleave",function(){for(var r=0;r<e.length;r++)e[r].style.transform=""})}}}}})();
